function EncodingValue([int]$id){$e=[Text.UTF8Encoding]::new(($id -eq 1 -or $id -eq 3),($id -eq 2 -or $id -eq 3));if($id -ge 4){$e=[Text.Encoding]$e.Clone();$replacement=if($id -eq 4){'XY'}else{''};$e.EncoderFallback=[Text.EncoderReplacementFallback]::new($replacement)};return $e}
$bridges=@{};$argsTypes=[type[]]@([Text.Encoder],[char[]],[int],[int],[byte[]],[int],[int],[bool],[int[]],[bool[]]);$nativeArgs=[type[]]@([char[]],[int],[int],[byte[]],[int],[int],[bool],[int].MakeByRefType(),[int].MakeByRefType(),[bool].MakeByRefType());$method=[Text.Encoder].GetMethod('Convert',$nativeArgs);foreach($alias in @($false,$true)){$bridge=[Reflection.Emit.DynamicMethod]::new(('EncoderConvertBoundary'+$alias),[void],$argsTypes);$il=$bridge.GetILGenerator();foreach($i in 0..7){$il.Emit([Reflection.Emit.OpCodes]::Ldarg,[int16]$i)};foreach($index in 0..1){$il.Emit([Reflection.Emit.OpCodes]::Ldarg,[int16]8);$il.Emit([Reflection.Emit.OpCodes]::Ldc_I4,$(if($alias){0}else{$index}));$il.Emit([Reflection.Emit.OpCodes]::Ldelema,[int])};$il.Emit([Reflection.Emit.OpCodes]::Ldarg,[int16]9);$il.Emit([Reflection.Emit.OpCodes]::Ldc_I4_0);$il.Emit([Reflection.Emit.OpCodes]::Ldelema,[bool]);$il.Emit([Reflection.Emit.OpCodes]::Callvirt,$method);$il.Emit([Reflection.Emit.OpCodes]::Ret);$action=[type]'System.Action`10';$bridges[[string]$alias]=$bridge.CreateDelegate($action.MakeGenericType($argsTypes))}
