function Form($overrides){$r=[ordered]@{kind='convert';units=[int[]]@(65,0xD800,66);srcNull=$false;destNull=$false;destLength=4;charIndex=0;charCount=3;byteIndex=0;byteCount=4;flush=$true;alias=$false};foreach($key in $overrides.Keys){$r[$key]=$overrides[$key]};return $r}
$forms=[Collections.Generic.List[object]]::new();foreach($index in @(-1,0,2,3,4,[int]::MaxValue)){foreach($count in @(-1,0,1,3,4,[int]::MaxValue)){$forms.Add((Form @{charIndex=$index;charCount=$count}))}};foreach($index in @(-1,0,3,4,5,[int]::MaxValue)){foreach($count in @(-1,0,1,4,5,[int]::MaxValue)){$forms.Add((Form @{byteIndex=$index;byteCount=$count}))}}
foreach($srcNull in @($false,$true)){foreach($destNull in @($false,$true)){foreach($negative in @($false,$true)){$forms.Add((Form @{srcNull=$srcNull;destNull=$destNull;charIndex=$(if($negative){-1}else{0});charCount=$(if($negative){-1}else{3});byteIndex=$(if($negative){-1}else{0});byteCount=$(if($negative){-1}else{4})}))}}}
$fields=@('charIndex','charCount','byteIndex','byteCount');for($i=0;$i -lt 4;$i++){for($k=$i+1;$k -lt 4;$k++){foreach($left in @(-1,[int]::MaxValue)){foreach($right in @(-1,[int]::MaxValue)){$patch=@{};$patch[$fields[$i]]=$left;$patch[$fields[$k]]=$right;$forms.Add((Form $patch))}}}}
