 try{switch($request.kind){'convert'{$arguments=[object[]]::new(10);$arguments[0]=[Text.Encoder]$encoder;$arguments[1]=[char[]]$chars;$arguments[2]=[int]$request.charIndex;$arguments[3]=[int]$request.charCount;$arguments[4]=[byte[]]$bytes;$arguments[5]=[int]$request.byteIndex;$arguments[6]=[int]$request.byteCount;$arguments[7]=[bool]$request.flush;$arguments[8]=$used;$arguments[9]=$completed;$bridges[[string][bool]$request.alias].DynamicInvoke($arguments)|Out-Null;$value=0}
