 'write'{$arguments=[object[]]::new(6);$arguments[0]=[char[]]$chars;$arguments[1]=[int]$request.charIndex;$arguments[2]=[int]$request.charCount;$arguments[3]=[byte[]]$bytes;$arguments[4]=[int]$request.byteIndex;$arguments[5]=[bool]$request.flush;$value=[int]$writeMethod.Invoke($encoder,$arguments)}
