 $destination=$null;if($null -ne $bytes){$destination=[int[]]$bytes};return [ordered]@{request=$request;result=$result;used=[int[]]$used;completed=$completed[0];destination=$destination;remaining=$encoder.FallbackBuffer.Remaining}
