$rows=[Collections.Generic.List[object]]::new();foreach($profile in 0..5){foreach($pending in @($false,$true)){foreach($request in $forms){$encoder=(EncodingValue $profile).GetEncoder();$steps=[Collections.Generic.List[object]]::new();if($pending){$steps.Add((Step $encoder (Form @{units=[int[]]@(0xD800);charCount=1;destLength=8;byteCount=8;flush=$false})))};$steps.Add((Step $encoder $request));$steps.Add((Step $encoder (Form @{units=[int[]]@(0xDC00);charCount=1;destLength=16;byteCount=16})));$steps.Add((Step $encoder (Form @{kind='reset';units=[int[]]@();charCount=0})));$rows.Add([ordered]@{family='validation';profile=$profile;pending=$pending;steps=$steps.ToArray()})}
 foreach($shape in @(@{units=[int[]]@(0xD800);charCount=1;byteCount=1},@{units=[int[]]@(65,0xD800);charCount=2;byteCount=2},@{units=[int[]]@();charCount=0;byteCount=0})){$encoder=(EncodingValue $profile).GetEncoder();$steps=[Collections.Generic.List[object]]::new();if($pending){$steps.Add((Step $encoder (Form @{units=[int[]]@(0xD800);charCount=1;destLength=8;byteCount=8;flush=$false})))};$steps.Add((Step $encoder (Form $shape)));foreach($kind in @('count','fallback','write','fallback','convert','reset','write')){$steps.Add((Step $encoder (Form @{kind=$kind;units=[int[]]@();charCount=0;destLength=16;byteCount=16})))};$rows.Add([ordered]@{family='cross-api';profile=$profile;pending=$pending;steps=$steps.ToArray()})}
}}
